import {build} from 'esbuild';
import {mkdir,readFile,writeFile,cp} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

export const projectRoot=fileURLToPath(new URL('..',import.meta.url));

/** Compile editable source/ into a separate runtime directory. Use
 * refreshRuntime for replacing the checkout's generated files safely. */
export async function bundleRuntime(destination,{root=projectRoot}={}){
  root=path.resolve(root);
  const output=path.resolve(destination);
  const authoring=path.join(root,'source');
  if(output===root||root.startsWith(output+path.sep)
    ||output===path.join(root,'src')||output.startsWith(path.join(root,'src')+path.sep)
    ||output===authoring||output.startsWith(authoring+path.sep))
    throw Error('Bundle output must be separate from the editable source.');
  const result=await build({
    absWorkingDir:root,entryPoints:['source/main.js'],outdir:path.join(output,'src'),
    entryNames:'[name]',chunkNames:'chunks/[name]-[hash]',bundle:true,splitting:true,
    format:'esm',platform:'browser',target:'es2022',metafile:true,write:true,
    sourcemap:true,keepNames:true,legalComments:'eof',
    // Whitespace only: preserve arithmetic expressions and property names.
    minifyWhitespace:true,minifyIdentifiers:false,minifySyntax:false,
    treeShaking:true,logLevel:'silent',
    banner:{js:'// Generated by npm run bundle. Edit source/ instead; see source/README.md.'},
  });
  const original=await readFile(path.join(root,'source/index.html'),'utf8');
  const html=original.replace(/\s*<script\s+type="importmap">[\s\S]*?<\/script>/,'');
  await mkdir(output,{recursive:true});
  await writeFile(path.join(output,'index.html'),html.replace(/<!doctype html>/i,
    '<!doctype html>\n<!-- Generated from source/index.html by npm run bundle. -->'));
  await cp(path.join(root,'source/style.css'),path.join(output,'src/style.css'));
  // Embedded debugging sources must retain stable identities when staging is
  // moved into the checkout or dist/ is deployed elsewhere. These virtual URLs
  // use sourcesContent; they do not request or execute individual source files.
  const outputs=await Promise.all(Object.entries(result.metafile.outputs).map(async([file,info])=>{
    const absolute=path.resolve(root,file);
    let bytes=info.bytes;
    if(file.endsWith('.map')){
      const map=JSON.parse(await readFile(absolute,'utf8'));
      map.sources=map.sources.map(source=>path.relative(root,path.resolve(path.dirname(absolute),source)).split(path.sep).join('/'));
      map.sourceRoot='rcsk-source:///';
      const text=JSON.stringify(map)+'\n';
      await writeFile(absolute,text);bytes=Buffer.byteLength(text);
    }
    return {path:path.relative(output,absolute).split(path.sep).join('/'),bytes};
  }));
  outputs.sort((a,b)=>a.path.localeCompare(b.path));
  const manifest={format:'rcsk-runtime-v1',entry:'src/main.js',
    files:[...outputs.filter(file=>file.path.endsWith('.js')).map(file=>file.path),'src/style.css'],
    sourceModules:Object.keys(result.metafile.inputs).length,
    javascriptBytes:outputs.filter(file=>file.path.endsWith('.js')).reduce((sum,file)=>sum+file.bytes,0),
    outputs};
  await writeFile(path.join(output,'runtime-manifest.json'),JSON.stringify(manifest,null,2)+'\n');
  return {manifest,metafile:result.metafile};
}
